bool ParseInternalKey(const Slice& internal_key, Slice* user_key, uint64_t* sequence, uint8_t* type) {
    const size_t kNumTagBytes = 8;
    if (internal_key.size() < kNumTagBytes) {
        return false;
    }

    // Extract user key (everything except the last 8 bytes)
    *user_key = Slice(internal_key.data(), internal_key.size() - kNumTagBytes);

    // Extract the packed sequence and type from the last 8 bytes
    const uint64_t tag = DecodeFixed64(internal_key.data() + internal_key.size() - kNumTagBytes);

    // Unpack sequence and type
    *sequence = tag >> 8;
    *type = static_cast<uint8_t>(tag & 0xff);

    // Validate type
    if (*type != kTypeValue && *type != kTypeDeletion) {
        return false;
    }

    return true;
}

